        /// <summary>Lista do esquema escolhido no IfcInfraConfiguration.json (Export.IfcVersion); sem esquema, IFC 4.3.</summary>
        public static string[] For(string ifcVersion) =>
            ifcVersion != null && ifcVersion.Trim().Equals("IFC4", StringComparison.OrdinalIgnoreCase) ? Ifc4 : Ifc4x3;

        /// <summary>Nome do esquema para mostrar.</summary>
        public static string Label(string ifcVersion) =>
            ifcVersion != null && ifcVersion.Trim().Equals("IFC4", StringComparison.OrdinalIgnoreCase) ? "IFC4" : "IFC 4.3 (IFC4X3_ADD2)";

        static readonly Dictionary<string[], HashSet<string>> Sets = new Dictionary<string[], HashSet<string>>();

        /// <summary>Vazio vale (classe da Autodesk). Compara sem diferenciar maiúsculas, como a Extension.</summary>
        public static bool IsValid(string value, string[] list)
        {
            if (string.IsNullOrWhiteSpace(value)) return true;
            lock (Sets)
            {
                if (!Sets.TryGetValue(list, out var set)) Sets[list] = set = new HashSet<string>(list, StringComparer.OrdinalIgnoreCase);
                return set.Contains(value.Trim());
            }
        }
    }
